class TrendChart extends StatelessWidget{final List<Habit> habits;final int days;const TrendChart({super.key,required this.habits,required this.days});@override Widget build(BuildContext context){final points=days<=7?7:days<=30?10:12;final values=<double>[];for(var i=points-1;i>=0;i--){final offset=(days/(points-1)*i).round();var done=0,total=0;final span=(days/(points-1)).round()<1?1:(days/(points-1)).round();for(var j=0;j<span;j++){final d=DateTime.now().subtract(Duration(days:offset-j));done+=habits.where((h)=>h.isScheduled(d)&&h.isDone(d)).length;total+=habits.where((h)=>h.isScheduled(d)).length;}values.add(total==0?0:done/total);}return SizedBox(height:170,child:CustomPaint(painter:TrendPainter(values),child:const SizedBox.expand()));}}
class TrendPainter extends CustomPainter{final List<double> values;TrendPainter(this.values);@override void paint(Canvas canvas,Size size){final p=Paint()..color=AppColors.blue..strokeWidth=3..style=PaintingStyle.stroke..strokeCap=StrokeCap.round;final fill=Paint()..color=AppColors.soft.withOpacity(.7)..style=PaintingStyle.fill;final path=Path();for(var i=0;i<values.length;i++){final x=values.length==1?0:size.width*i/(values.length-1);final y=size.height-20-values[i]*(size.height-45);if(i==0)path.moveTo(x,y);else path.lineTo(x,y);}canvas.drawPath(path,p);final fillPath=Path()..moveTo(0,size.height-20);for(var i=0;i<values.length;i++){final x=values.length==1?0:size.width*i/(values.length-1);final y=size.height-20-values[i]*(size.height-45);fillPath.lineTo(x,y);}fillPath.lineTo(size.width,size.height-20);fillPath.close();canvas.drawPath(fillPath,fill);for(var i=0;i<values.length;i++){final x=values.length==1?0:size.width*i/(values.length-1);final y=size.height-20-values[i]*(size.height-45);canvas.drawCircle(Offset(x,y),4,Paint()..color=AppColors.blue);}}@override bool shouldRepaint(covariant TrendPainter oldDelegate)=>oldDelegate.values!=values;}
class ActivityHeatmap extends StatelessWidget{final List<Habit> habits;final int year;final String habitName;const ActivityHeatmap({super.key,required this.habits,required this.year,required this.habitName});@override Widget build(BuildContext context){Habit? target;if(habitName!='All habits'){for(final h in habits){if(h.name==habitName){target=h;break;}}}final jan=DateTime(year,1,1);final start=jan.subtract(Duration(days:jan.weekday-1));final end=DateTime(year,12,31);final weeks=<List<DateTime>>[];var cursor=start;while(cursor.isBefore(end)||Habit.key(cursor)==Habit.key(end)){final col=<DateTime>[];for(var r=0;r<7;r++){col.add(cursor.add(Duration(days:r)));}weeks.add(col);cursor=cursor.add(const Duration(days:7));}return SingleChildScrollView(scrollDirection:Axis.horizontal,child:Row(crossAxisAlignment:CrossAxisAlignment.start,children:weeks.map((week)=>Padding(padding:const EdgeInsets.only(right:3),child:Column(children:week.map((d){final inYear=d.year==year;final done=target==null?habits.where((h)=>h.isScheduled(d)&&h.isDone(d)).length:(target.isScheduled(d)&&target.isDone(d)?1:0);final scheduled=target==null?habits.where((h)=>h.isScheduled(d)).length:(target.isScheduled(d)?1:0);final int level=!inYear||scheduled==0?0:((done/scheduled)*4).ceil().clamp(0,4).toInt();return Padding(padding:const EdgeInsets.only(bottom:3),child:Tooltip(message:'${DateFormat('d MMM yyyy').format(d)} · $done/$scheduled',child:Container(width:12,height:12,decoration:BoxDecoration(color:heatColor(level),borderRadius:BorderRadius.circular(3)))));})).toList()))).toList()));}}
