ild:Text(x))).toList(),onChanged:(v){if(v!=null)setState(()=>category=v);})),const SizedBox(width:10),Expanded(child:DropdownButtonFormField<String>(value:unit,items:units.map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v){if(v!=null)setState(()=>unit=v);}))]),const SizedBox(height:10),TextField(controller:goal,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Target')),const SizedBox(height:10),const Text('Frequency',style:TextStyle(fontWeight:FontWeight.w800)),Wrap(spacing:5,children:['Every day','Weekdays','Custom'].map((x)=>ChoiceChip(label:Text(x),selected:frequency==x,onSelected:(_)=>setState(()=>frequency=x))).toList()),if(frequency=='Custom')Padding(padding:const EdgeInsets.symmetric(vertical:8),child:Wrap(spacing:4,children:List.generate(7,(i){final d=i+1;return FilterChip(label:Text(['M','T','W','T','F','S','S'][i]),selected:weekdays.contains(d),onSelected:(v)=>setState(()=>v?weekdays.add(d):weekdays.remove(d)));}))),TextField(controller:tags,decoration:const InputDecoration(labelText:'Tags, comma separated')),const SizedBox(height:8),TextField(controller:notes,maxLines:3,decoration:const InputDecoration(labelText:'Journal / notes')),SwitchListTile(contentPadding:EdgeInsets.zero,value:pinned,onChanged:(v)=>setState(()=>pinned=v),title:const Text('Pin to top')),SwitchListTile(contentPadding:EdgeInsets.zero,value:active,onChanged:(v)=>setState(()=>active=v),title:const Text('Active')),if(widget.habit!=null)TextButton.icon(onPressed:()=>Navigator.pop(context,const HabitEdit(name:'',category:'',goal:1,unit:'times',frequency:'Every day',weekdays:[1,2,3,4,5,6,7],pinned:false,active:false,tags:[],notes:'',delete:true)),icon:const Icon(Icons.delete_outline),label:const Text('Delete')),FilledButton(onPressed:save,style:FilledButton.styleFrom(minimumSize:const Size.fromHeight(52)),child:Text(widget.habit==null?'Create habit':'Save changes'))]))));}
